script.setup:
// Plays the bundled loop and analyses it (click the viewport if the browser blocked autoplay).
await ctx.utils.audio.play("beat.wav", { loop: true, volume: 0.8 });
ctx.state.tex = ctx.utils.audioTexture();
ctx.state.p = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;
uniform sampler2D u_audioTex;
uniform vec4 u_audio;
uniform vec2 u_resolution;
uniform float u_bars;
uniform vec3 u_low;
uniform vec3 u_high;
void main() {
  vec2 uv = v_uv;
  float i = floor(uv.x * u_bars);
  // Low frequencies get more bars (the spectrum is linear in frequency).
  int bin = int(pow(i / u_bars, 1.8) * 200.0);
  float level = texelFetch(u_audioTex, ivec2(bin, 0), 0).r;
  float bar = step(uv.y, 0.06 + level * 0.78) * step(0.18, fract(uv.x * u_bars));
  vec3 col = mix(u_low, u_high, uv.y) * bar;
  vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution) / u_resolution.y;
  float ring = smoothstep(0.015, 0.0, abs(length(p - vec2(0.0, 0.18)) - (0.08 + u_audio.y * 0.22)));
  col += u_high * ring * (0.3 + u_audio.y);
  float w = texelFetch(u_audioTex, ivec2(int(uv.x * 255.0), 1), 0).r;
  col += vec3(0.9) * smoothstep(0.005, 0.0, abs(uv.y - (0.93 + w * 0.05)));
  outColor = vec4(col + vec3(0.015, 0.012, 0.03), 1.0);
}");

script.render:
const p = ctx.state.p;
ctx.gl.useProgram(p);
ctx.utils.bindTexture(p, "u_audioTex", ctx.state.tex, 0);
ctx.utils.drawFullscreen(p);
ctx.publish("bass", ctx.audio.bass);
ctx.publish("level", ctx.audio.level);
